{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "GSK1322322, which shares the aniline-aminopyrimidine, methoxy, and basic amine features of the query, had 77% absolute oral bioavailability in healthy volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Deucravacitinib, an oral kinase inhibitor with a heteroaromatic core and amide functionality, showed 99% absolute oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Brepocitinib, containing an aminopyrimidine and N-methyl azole similar to the query, had 75% absolute oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "R406, an aminopyrimidine kinase inhibitor with methoxyphenyl and amide groups, had 54.6% oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "ZL-2201, a structurally related aminopyrimidine kinase inhibitor, was predicted to have ~70% human oral bioavailability at low dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Silodosin, a basic amine drug with amide/ether functionality, had 32.2% absolute oral bioavailability, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Nilotinib, an aminopyrimidine kinase inhibitor, had predicted bioavailability as low as 16% at 400 mg in fasted volunteers due to solubility-limited absorption, providing a contradictory lower-F scenario.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Isradipine, which contains an isopropyl ester like the query, had systemic availability of 16.5% in volunteers, a sub-20% example that is less structurally related overall.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transfer analogues are structurally related aminopyrimidine kinase inhibitors with measured absolute oral bioavailability of 54–99%, all above the 20% threshold; the query's basic amine and amide/heteroaromatic features align with these high-F compounds. The sub-20% examples are either less structurally relevant (isradipine) or dose/solubility-limited (nilotinib) and do not outweigh the consistent high-F evidence. Therefore F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "The isopropyl ester and acrylamide warhead are not present in the high-F analogues; their metabolic stability and absorption contribution are uncertain.",
    "Nilotinib demonstrates that solubility can reduce F in this chemotype, so the query's solubility/dose behavior is not fully constrained."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

